import { readResponseAsFile } from './responseUtils.js';
/**
 * Prefetch and cache data from a URL. A later call to
 * {@link @imfusion/sdk!ImFusion.loadFileFromUrl | imf.loadFileFromUrl()} with the same URL
 * will use the cached bytes or take ownership of the fetch if still in flight.
 *
 * The data is removed from cache when consumed by loadFileFromUrl, or when
 * discarded via the signal or {@link clearPrefetch}.
 *
 * @example
 * ```ts
 * import { prefetch } from '@imfusion/sdk';
 *
 * const ac = new AbortController();
 * prefetch('/scans/ct.nii.gz', { signal: ac.signal });
 *
 * // user navigates away before opening:
 * ac.abort();
 *
 * // or user opens the file:
 * const data = await imf.loadFileFromUrl('/scans/ct.nii.gz'); // hits the cached prefetch
 * ```
 * @param options.signal - Aborts the fetch and discards any bytes already downloaded.
 * @param options.priority - Fetch priority hint. Use `'low'` for background prefetching.
 */
export function prefetch(url, options) {
    const signal = options?.signal;
    if (signal?.aborted)
        return;
    let entry = cache.get(url);
    if (!entry) {
        entry = create(url, options?.priority);
        cache.set(url, entry);
    }
    if (signal) {
        const entryForSignal = entry;
        signal.addEventListener('abort', () => {
            // Once removed, evictionController detaches this listener, so it
            // can only fire while entryForSignal is still the current entry.
            remove(url, entryForSignal);
            entryForSignal.fetchController.abort();
        }, { once: true, signal: entryForSignal.evictionController.signal });
    }
}
/**
 * Abort any in-flight fetch for this URL and remove the fetched data.
 *
 * No-op if there's no entry for the URL.
 */
export function clearPrefetch(url) {
    const entry = cache.get(url);
    if (!entry)
        return;
    remove(url, entry);
    entry.fetchController.abort();
}
const cache = new Map();
/**
 * Take the cached entry for `url` and return its promise, or `null` for
 * a miss. The returned promise resolves with the FetchedFile.
 *
 * If `onProgress` is provided, it receives only chunks that arrive after this
 * call attaches it.
 *
 * @internal
 */
export function consumePrefetch(url, options) {
    const entry = cache.get(url);
    if (!entry)
        return null;
    remove(url, entry);
    if (options?.onProgress)
        entry.progress = options.onProgress;
    const signal = options?.signal;
    if (signal) {
        if (signal.aborted) {
            entry.fetchController.abort();
        }
        else {
            const abort = () => entry.fetchController.abort();
            signal.addEventListener('abort', abort, { once: true });
            const detach = () => signal.removeEventListener('abort', abort);
            entry.promise.then(detach, detach);
        }
    }
    return entry.promise;
}
/** @internal */
export function clearAllPrefetches() {
    for (const [url, entry] of cache) {
        remove(url, entry);
        entry.fetchController.abort();
    }
}
function remove(url, entry) {
    cache.delete(url);
    entry.evictionController.abort();
}
function create(url, priority) {
    const fetchController = new AbortController();
    const evictionController = new AbortController();
    // Definite-assignment: the closure below only dereferences `entry` after
    // its first `await`, by which time `entry` has been assigned.
    let entry;
    const promise = (async () => {
        try {
            const response = await fetch(url, { signal: fetchController.signal, priority });
            if (!response.ok) {
                throw new Error(`Failed to fetch ${url}: ${response.status} ${response.statusText}`);
            }
            return await readResponseAsFile(response, url, (received, total) => {
                entry.progress?.(received, total);
            });
        }
        catch (err) {
            // The entry may have been consumed and replaced by a newer prefetch
            // while this fetch was in flight.
            if (cache.get(url) === entry)
                remove(url, entry);
            throw err;
        }
    })();
    entry = { promise, fetchController, evictionController, progress: null };
    // Avoid an unhandled rejection in case nobody actually awaits the promise.
    promise.catch(() => { });
    return entry;
}
